function Crowd() {
  const fans = useMemo(() => {
    const out: { x: number; y: number; c: string; skin: string }[] = [];
    for (const y of [4.6, 10.6, 90.6, 96.6]) for (let x = 2.5 + (y % 2) * 1.6; x < 178; x += 4.2) out.push({ x, y, c: TEAM_COLORS[Math.floor(Math.random() * TEAM_COLORS.length)], skin: SKINS[Math.floor(Math.random() * SKINS.length)] });
    return out;
  }, []);
  return <>{fans.map((f, i) => <g key={i}><path d={`M${f.x - 1.8} ${f.y + 2.2} q0 -2.6 1.8 -2.6 q1.8 0 1.8 2.6 z`} fill={f.c} stroke="#000" strokeWidth="0.25" /><circle cx={f.x} cy={f.y - 1.4} r="1.3" fill={f.skin} stroke="#000" strokeWidth="0.25" /></g>)}</>;
}

